# Ensure uniqueness and check against prior chapters
clean_ch10 = []
seen_local = set()

for word, meaning, example in raw_professional_words:
    w_clean = word.upper().replace(" ", "").replace("-", "")
    if w_clean in used_words:
        print(f"Skipping overlap word: {w_clean}")
        continue
    if w_clean in seen_local:
        print(f"Skipping duplicate in raw list: {w_clean}")
        continue
    seen_local.add(w_clean)
    clean_ch10.append({
        "word": w_clean,
        "meaning": meaning,
        "example": example
    })

print(f"Total raw words prepared: {len(raw_professional_words)}")
print(f"Total valid unique Ch10 words: {len(clean_ch10)}")

assert len(clean_ch10) >= 364, f"Need at least 364 words, got {len(clean_ch10)}"

# Trim to exactly 364 words
clean_ch10 = clean_ch10[:364]

os.makedirs("scratch", exist_ok=True)
